import { withCSS } from "framer"
import { AnimatePresence, motion } from "framer-motion"
import {
    type CSSProperties,
    lazy,
    type MouseEvent,
    type ReactNode,
    Suspense,
    useState,
} from "react"
import type { ConsentModeName, ConsentModes } from "../hooks/consent.ts"
import type { RegionContent } from "../hooks/region.ts"
import type {
    ButtonsProps,
    OptionsStyle,
    PolicyProps,
    CookieBannerProps,
    FontProps,
} from "../Cookies.tsx"
import { DEFAULT_FONT_FAMILY, getMultipleShadows, getShadow } from "./utils.ts"

const SPACING = 20

export type BannerComponentProps = Pick<
    CookieBannerProps,
    "banner" | "button" | "options"
> & {
    region: RegionContent
    previewOptions?: boolean
    consentModes: ConsentModes
    animateOnMount: boolean
    onDismiss?: () => void
    onAcceptAll?: () => void
    onRejectAll?: () => void
    onAcceptCurrent?: () => void
    onToggleConsent?: (mode: ConsentModeName) => void
}

// if you update the Toggle component inside this project, copy the new URL to here:
const Toggle = lazy(
    () =>
        import(
            "https://framerusercontent.com/modules/QDCSmi7dYWSK5AcRSFyX/sBWK1WbcsjrFOSoIzxuJ/Blf0sjosZ.js"
        )
)

export const Banner = withCSS<BannerComponentProps>(
    function Banner({
        banner,
        button,
        region,
        options,
        previewOptions,
        consentModes,
        onDismiss,
        onAcceptAll,
        onRejectAll,
        onAcceptCurrent,
        onToggleConsent,
        animateOnMount,
    }: BannerComponentProps) {
        const maxHeightReduction = banner.insetPerSide
            ? banner.insetTop + banner.insetBottom
            : banner.inset * 2

        const linkColor = banner.style.link || button.primary.fill

        const bannerShadow = getShadow(banner.style.shadow)
        const borderShadow = banner.style.border?.width
            ? `inset 0 0 0 ${banner.style.border.width}px ${banner.style.border.color}`
            : null

        const bannerStyle = {
            background: banner.style.fill,
            boxShadow: getMultipleShadows(bannerShadow, borderShadow),
            overflow: "hidden",
            borderRadius: banner.style.border.radius,
        }

        return (
            <motion.div
                initial={
                    animateOnMount && {
                        x: banner.animation.x,
                        y: banner.animation.y,
                        scale: banner.animation.scale,
                        opacity: 0,
                    }
                }
                animate={{
                    y: 0,
                    x: 0,
                    scale: 1,
                    opacity: 1,
                }}
                exit={{
                    x: banner.animation.x,
                    y: banner.animation.y,
                    scale: banner.animation.scale,
                    opacity: 0,
                }}
                transition={
                    animateOnMount
                        ? banner.animation.transition
                        : { duration: 0 }
                }
                style={{
                    maxHeight: `calc(100vh - ${maxHeightReduction}px)`,
                    flexDirection: "column",
                    gap: 12,
                    position: "relative",
                    display: "flex",
                    zIndex: 100,
                    pointerEvents: "auto",
                }}
            >
                <div
                    style={{
                        ...bannerStyle,
                        overflow: "scroll",
                        width: "100%",
                        maxWidth: banner.width,
                    }}
                    className={`--framer-cookie-banner-container --framer-cookie-banner-type-${region.type}`}
                >
                    {region.type === "simple" ? (
                        <SimpleBanner
                            banner={banner}
                            button={button}
                            linkColor={linkColor}
                            description={region.description}
                            policy={region.policy}
                            onDismiss={onDismiss}
                        />
                    ) : region.type === "medium" ? (
                        <AcceptRejectBanner
                            banner={banner}
                            button={button}
                            linkColor={linkColor}
                            title={region.title}
                            description={region.description}
                            policy={region.policy}
                            onAccept={onAcceptAll}
                            onReject={onRejectAll}
                        />
                    ) : (
                        <OptionsBanner
                            banner={banner}
                            button={button}
                            options={options}
                            previewOptions={previewOptions}
                            linkColor={linkColor}
                            title={region.title}
                            description={region.description}
                            showReject={region.showReject}
                            policy={region.policy}
                            onOptionToggle={onToggleConsent}
                            consent={consentModes}
                            onAcceptAll={onAcceptAll}
                            onRejectAll={onRejectAll}
                            onAcceptCurrent={onAcceptCurrent}
                        />
                    )}
                </div>
            </motion.div>
        )
    },
    [
        `.--framer-cookie-banner-container::-webkit-scrollbar { display: none; }`,
        `.--framer-cookie-banner-container { 
            -ms-overflow-style: none; 
            scrollbar-width: none;  
        }`,
    ],
    "framer-lib-cookie-banner"
)

type SimpleBannerProps = Pick<BannerComponentProps, "banner" | "button"> & {
    linkColor: string
    description: string
    policy?: PolicyProps
    onDismiss: () => void
}

function SimpleBanner({
    banner,
    button,
    description,
    policy,
    onDismiss,
    linkColor,
}: SimpleBannerProps) {
    const padding = banner.paddingPerSide
        ? `${banner.paddingTop}px ${banner.paddingRight}px ${banner.paddingBottom}px ${banner.paddingLeft}px`
        : `${banner.padding}px`

    return (
        <div
            style={{
                display: "flex",
                flexDirection: "row",
                padding,
                gap: SPACING,
            }}
        >
            <Description
                style={{
                    ...withDefaultFontFamily(banner.style.fontBody),
                    flex: 1,
                    alignItems: "center",
                    color: banner.style.colorBody,
                }}
                linkColor={linkColor}
                description={description}
                policy={policy}
            />

            <motion.div
                style={{
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                }}
            >
                <Button
                    onClick={onDismiss}
                    settings={{ ...button, fluid: false }}
                    id="dismiss"
                >
                    {button.labels.confirm}
                </Button>
            </motion.div>
        </div>
    )
}

type AcceptRejectProps = Pick<BannerComponentProps, "banner" | "button"> & {
    title: string
    description: string
    linkColor: string
    policy?: PolicyProps
    onReject?: () => void
    onAccept?: () => void
}

function AcceptRejectBanner({
    banner,
    button,
    title,
    linkColor,
    description,
    policy,
    onAccept,
    onReject,
}: AcceptRejectProps) {
    const padding = banner.paddingPerSide
        ? `${banner.paddingTop}px ${banner.paddingRight}px ${banner.paddingBottom}px ${banner.paddingLeft}px`
        : `${banner.padding}px`

    return (
        <div
            style={{
                padding,
            }}
        >
            <div>
                {title && (
                    <Headline
                        style={{
                            ...withDefaultFontFamily(banner.style.fontTitle),
                            color: banner.style.colorTitle,
                        }}
                    >
                        {title}
                    </Headline>
                )}
                <Description
                    style={{
                        ...withDefaultFontFamily(banner.style.fontBody),
                        color: banner.style.colorBody,
                    }}
                    linkColor={linkColor}
                    description={description}
                    policy={policy}
                />
            </div>
            <Buttons direction={button.direction}>
                <Button settings={button} onClick={onReject} id="reject">
                    {button.labels.reject}
                </Button>
                <Button
                    settings={button}
                    primary
                    onClick={onAccept}
                    id="accept"
                >
                    {button.labels.accept}
                </Button>
            </Buttons>
        </div>
    )
}

type OptionsBannerProps = Pick<
    BannerComponentProps,
    "banner" | "button" | "options"
> & {
    title: string
    description: string
    policy?: PolicyProps
    showReject: boolean
    linkColor: string
    consent: ConsentModes
    previewOptions?: boolean
    onAcceptCurrent: () => void
    onAcceptAll: () => void
    onRejectAll: () => void
    onOptionToggle: (type: ConsentModeName) => void
}

function OptionsBanner({
    banner,
    button,
    options,
    previewOptions,
    title,
    description,
    policy,
    showReject = true,
    linkColor,
    consent,
    onAcceptCurrent,
    onAcceptAll,
    onRejectAll,
    onOptionToggle,
}: OptionsBannerProps) {
    const [showOptions, setShowOptions] = useState(false)
    const optionTheme = { ...options.style, color: banner.style.colorBody }
    const padding = banner.paddingPerSide
        ? `${banner.paddingTop}px ${banner.paddingRight}px ${banner.paddingBottom}px ${banner.paddingLeft}px`
        : `${banner.padding}px`

    // const optionNames = consent && Object.keys(consent)

    const optionNames: Array<ConsentModeName> = [
        "necessary",
        "preferences",
        "analytics",
        "marketing",
    ]

    const shouldShowOptions = showOptions || previewOptions

    return (
        <div
            style={{
                padding,
            }}
        >
            <div>
                {title && (
                    <Headline
                        style={{
                            ...withDefaultFontFamily(banner.style.fontTitle),
                            color: banner.style.colorTitle,
                        }}
                    >
                        {title}
                    </Headline>
                )}
                <Description
                    style={{
                        ...withDefaultFontFamily(banner.style.fontBody),
                        color: banner.style.colorBody,
                    }}
                    linkColor={linkColor}
                    description={description}
                    policy={policy}
                />
                <AnimatePresence>
                    {shouldShowOptions && (
                        <motion.div
                            key="modal"
                            initial={
                                previewOptions
                                    ? null
                                    : { opacity: 0, height: 0 }
                            }
                            animate={{ opacity: 1, height: "auto" }}
                            exit={{ opacity: 0, height: 0 }}
                            style={{
                                display: "flex",
                                flexDirection: "column",
                                gap: 10,
                                marginTop: SPACING,
                                overflow: "hidden",
                            }}
                        >
                            {optionNames &&
                                optionNames.map((option: ConsentModeName) => (
                                    <Option
                                        title={options[option].title}
                                        description={
                                            options[option].description
                                        }
                                        titleColor={banner.style.colorTitle}
                                        descriptionColor={
                                            banner.style.colorBody
                                        }
                                        showDescription={options.descriptions}
                                        enabled={consent[option]}
                                        onClick={() => onOptionToggle(option)}
                                        theme={optionTheme}
                                        optional={
                                            option === "necessary"
                                                ? options[option].optional
                                                : true
                                        }
                                    />
                                ))}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            <Buttons direction={button.direction}>
                {shouldShowOptions ? (
                    <Button
                        settings={button}
                        primary
                        onClick={onAcceptCurrent}
                        id="accept"
                    >
                        {button.labels.save}
                    </Button>
                ) : (
                    <>
                        {showReject && (
                            <Button
                                settings={button}
                                onClick={onRejectAll}
                                id="reject"
                            >
                                {button.labels.rejectAll}
                            </Button>
                        )}
                        <Button
                            settings={button}
                            onClick={() => {
                                setShowOptions(true)
                            }}
                            id="customize"
                        >
                            {button.labels.customize}
                        </Button>
                        <Button
                            settings={button}
                            primary
                            onClick={onAcceptAll}
                            id="accept"
                        >
                            {button.labels.acceptAll}
                        </Button>
                    </>
                )}
            </Buttons>
        </div>
    )
}

type OptionProps = {
    title: string
    titleColor: string
    description: string
    descriptionColor: string
    showDescription: boolean
    enabled: boolean
    onClick: () => void
    theme: OptionsStyle
    optional?: boolean
}

function Option({
    title,
    titleColor,
    description,
    descriptionColor,
    showDescription,
    enabled,
    optional,
    onClick,
    theme,
}: OptionProps) {
    const paddingValue = theme.paddingPerSide
        ? `${theme.paddingTop}px ${theme.paddingRight}px ${theme.paddingBottom}px ${theme.paddingLeft}px`
        : `${theme.padding}px`

    const borderShadow = theme.border
        ? `inset 0 0 0 ${theme.border.width}px ${theme.border.color}`
        : null

    return (
        <motion.div
            style={{
                boxShadow: borderShadow,
                background: theme.background,
                borderRadius: theme.border.radius,
                padding: paddingValue,
                cursor: "pointer",
                userSelect: "none",
                pointerEvents: "all",
            }}
            onClick={onClick}
            whileHover={{ opacity: 0.5 }}
        >
            <div
                style={{
                    display: "flex",
                    justifyContent: "space-between",
                }}
            >
                <p
                    style={{
                        margin: 0,
                        fontWeight: 600,
                        fontSize: 12,
                        color: titleColor,
                        ...withDefaultFontFamily(theme.fontTitle),
                    }}
                >
                    {title}
                </p>
                {optional ? (
                    <Suspense fallback={null}>
                        <Toggle
                            variant={enabled ? "On" : "Off"}
                            background={theme.toggleColor}
                            backgroundInactive={theme.toggleColorInactive}
                            ariaLabel={`Toggle for ${title}`}
                        />
                    </Suspense>
                ) : (
                    <p
                        style={{
                            margin: 0,
                            fontSize: 12,
                            color: theme.toggleColor,
                            ...withDefaultFontFamily(theme.fontTitle),
                            fontWeight: 400,
                        }}
                    >
                        Always active
                    </p>
                )}
            </div>
            {description && (
                <p
                    style={{
                        margin: 0,
                        marginTop: 10,
                        fontSize: 12,
                        lineHeight: 1.5,
                        color: descriptionColor,
                        ...withDefaultFontFamily(theme.fontBody),
                    }}
                >
                    {description}
                </p>
            )}
        </motion.div>
    )
}

function Headline({
    children,
    style,
}: {
    children: ReactNode
    style: CSSProperties
}) {
    return (
        <p
            style={{
                fontSize: 14,
                margin: "0px 0px 10px 0px",
                fontWeight: "bold",
                padding: 0,
                ...style,
            }}
        >
            {children}
        </p>
    )
}

function Description({
    style,
    description,
    policy,
    linkColor,
}: {
    style: CSSProperties
    description: string
    policy: PolicyProps
    linkColor: string
}) {
    const shouldShow = description || policy?.link

    if (!shouldShow) return null

    if (!description) {
        return (
            <DescriptionParagraph
                policy={policy}
                style={style}
                linkColor={linkColor}
            />
        )
    }

    // @ivan: Support rendering the description in multiple paragraphs.
    // This is a site speed optimization: it allows to split a single
    // huge <p> into several smaller ones, which prevents the huge <p>
    // from becoming an LCP element.
    const descriptionParagraphs = description?.split("\n\n")

    return description.split("\n\n").map((line, index) => (
        <DescriptionParagraph
            key={index}
            line={line}
            // Only render the policy in the last paragraph
            policy={index === descriptionParagraphs.length - 1 ? policy : null}
            style={{
                // Add a spacing between paragraphs
                marginTop: index > 0 ? 4 : 0,
                ...style,
            }}
            linkColor={linkColor}
        />
    ))
}

function DescriptionParagraph({
    line,
    policy,
    style,
    linkColor,
}: {
    line?: string
    policy?: PolicyProps
    style: CSSProperties
    linkColor: string
}) {
    return (
        <p
            style={{
                lineHeight: 1.5,
                margin: 0,
                padding: 0,
                fontSize: 14,
                ...style,
            }}
        >
            {line}
            {line && policy?.link ? " " : null}
            {policy?.link && (
                <span>
                    {policy?.prefix}{" "}
                    <a
                        href={policy?.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        style={{
                            color: linkColor,
                            textDecoration: "none",
                        }}
                    >
                        {policy?.label}
                    </a>
                    .
                </span>
            )}
        </p>
    )
}

type ButtonComponentProps = {
    children: ReactNode
    settings: ButtonsProps
    primary?: boolean
    onClick?: (e: MouseEvent<HTMLButtonElement>) => void
    id?: string
}

function Buttons({
    children,
    direction,
}: {
    children: ReactNode
    direction: "row" | "column"
}) {
    return (
        <div
            style={{
                display: "flex",
                flexDirection: direction,
                gap: 10,
                marginTop: 16,
            }}
        >
            {children}
        </div>
    )
}

const Button = withCSS(
    function Button({
        id,
        children,
        primary,
        settings,
        onClick,
    }: ButtonComponentProps) {
        const paddingValue = settings.paddingPerSide
            ? `${settings.paddingTop}px ${settings.paddingRight}px ${settings.paddingBottom}px ${settings.paddingLeft}px`
            : `${settings.padding}px`

        const theme = primary ? settings.primary : settings.secondary

        return (
            <motion.input
                className="__framer-cookie-component-button"
                id={`__framer-cookie-component-button-${id}`}
                onClick={onClick}
                type="button"
                value={`${children}`}
                whileHover={{
                    opacity: settings.hoverOpacity ?? 0.6,
                }}
                whileTap={{ opacity: settings.tapOpacity ?? 0.4 }}
                style={{
                    WebkitAppearance: "none",
                    appearance: "none",
                    width: settings.fluid ? "100%" : "auto",
                    height: "auto",
                    border: "none",
                    padding: paddingValue,
                    borderRadius: settings.borderRadius,
                    boxShadow: getShadow(theme.shadow),
                    background: theme.fill,
                    color: theme.color,
                    fontSize: 14,
                    lineHeight: 1,
                    cursor: "pointer",
                    fontWeight: settings.font ? "unset" : 600,
                    ...withDefaultFontFamily(settings.font),
                }}
            />
        )
    },
    ".__framer-cookie-component-button:focus:not(:focus-visible){outline-color:transparent}",
    "framer-lib-cookie-banner"
)

function withDefaultFontFamily(style: FontProps | undefined) {
    if (style?.fontFamily) return style

    return {
        ...style,
        fontFamily: style?.fontFamily || DEFAULT_FONT_FAMILY,
    }
}
